21	/// Thread builder used for customization via [`ThreadPoolBuilder::spawn_handler()`].
22	pub struct ThreadBuilder {
23	    name: Option<String>,
24	    stack_size: Option<usize>,
25	    worker: Worker<JobRef>,
26	    stealer: Stealer<JobRef>,
27	    registry: Arc<Registry>,
28	    index: usize,
29	}
