65	/// Generalized trait for spawning a thread in the `Registry`.
66	///
67	/// This trait is crate-private, because we don't actually want to
68	/// expose these details in the API.
69	pub(crate) trait ThreadSpawn {
70	    /// Spawn a thread with the `ThreadBuilder` parameters, and then
71	    /// call `ThreadBuilder::run()`.
72	    fn spawn(&mut self, thread: ThreadBuilder) -> io::Result<()>;
73	}
74	
75	/// Spawns a thread in the "normal" way with `std::thread::Builder`.
76	///
77	/// This type is pub-in-private -- it has to be somewhat exposed to be
78	/// usable as a type parameter of `ThreadPoolBuilder`, but we don't
79	/// actually want to expose these details in the API.
80	#[derive(Debug, Default)]
81	#[expect(unnameable_types)]
82	pub struct DefaultSpawn;
83	
84	impl ThreadSpawn for DefaultSpawn {
85	    fn spawn(&mut self, thread: ThreadBuilder) -> io::Result<()> {
86	        let mut b = thread::Builder::new();
87	        if let Some(name) = thread.name() {
88	            b = b.name(name.to_owned());
89	        }
90	        if let Some(stack_size) = thread.stack_size() {
91	            b = b.stack_size(stack_size);
92	        }
93	        b.spawn(|| thread.run())?;
94	        Ok(())
95	    }
96	}
