98	/// Spawns a thread with a user's custom callback.
99	///
100	/// This type is pub-in-private -- it has to be somewhat exposed to be
101	/// usable as a type parameter of `ThreadPoolBuilder`, but we don't
102	/// actually want to expose these details in the API.
103	#[derive(Debug)]
104	#[expect(unnameable_types)]
105	pub struct CustomSpawn<F>(F);
106	
107	impl<F> CustomSpawn<F>
108	where
109	    F: FnMut(ThreadBuilder) -> io::Result<()>,
110	{
111	    pub(super) fn new(spawn: F) -> Self {
112	        CustomSpawn(spawn)
113	    }
