117	where
118	    F: FnMut(ThreadBuilder) -> io::Result<()>,
119	{
120	    #[inline]
121	    fn spawn(&mut self, thread: ThreadBuilder) -> io::Result<()> {
122	        (self.0)(thread)
123	    }
