153	
154	static mut THE_REGISTRY: Option<Arc<Registry>> = None;
155	static THE_REGISTRY_SET: Once = Once::new();
156	
157	/// Starts the worker threads (if that has not already happened). If
158	/// initialization has not already occurred, use the default
159	/// configuration.
160	pub(super) fn global_registry() -> &'static Arc<Registry> {
161	    set_global_registry(default_global_registry)
162	        .or_else(|err| {
163	            // SAFETY: we only create a shared reference to `THE_REGISTRY` after the `call_once`
164	            // that initializes it, and there will be no more mutable accesses at all.
165	            debug_assert!(THE_REGISTRY_SET.is_completed());
166	            let the_registry = unsafe { &*ptr::addr_of!(THE_REGISTRY) };
167	            the_registry.as_ref().ok_or(err)
168	        })
169	        .expect("The global thread pool has not been initialized.")
170	}
171	
172	/// Starts the worker threads (if that has not already happened) with
173	/// the given builder.
174	pub(super) fn init_global_registry<S>(
175	    builder: ThreadPoolBuilder<S>,
176	) -> Result<&'static Arc<Registry>, ThreadPoolBuildError>
177	where
178	    S: ThreadSpawn,
179	{
180	    set_global_registry(|| Registry::new(builder))
181	}
182	
183	/// Starts the worker threads (if that has not already happened)
184	/// by creating a registry with the given callback.
185	fn set_global_registry<F>(registry: F) -> Result<&'static Arc<Registry>, ThreadPoolBuildError>
186	where
187	    F: FnOnce() -> Result<Arc<Registry>, ThreadPoolBuildError>,
188	{
189	    let mut result = Err(ThreadPoolBuildError::new(
190	        ErrorKind::GlobalPoolAlreadyInitialized,
191	    ));
192	
193	    THE_REGISTRY_SET.call_once(|| {
194	        result = registry().map(|registry: Arc<Registry>| {
195	            // SAFETY: this is the only mutable access to `THE_REGISTRY`, thanks to `Once`, and
196	            // `global_registry()` only takes a shared reference **after** this `call_once`.
197	            unsafe {
198	                ptr::addr_of_mut!(THE_REGISTRY).write(Some(registry));
199	                (*ptr::addr_of!(THE_REGISTRY)).as_ref().unwrap_unchecked()
200	            }
201	        })
202	    });
203	
204	    result
205	}
206	
207	fn default_global_registry() -> Result<Arc<Registry>, ThreadPoolBuildError> {
208	    let result = Registry::new(ThreadPoolBuilder::new());
209	
210	    // If we're running in an environment that doesn't support threads at all, we can fall back to
211	    // using the current thread alone. This is crude, and probably won't work for non-blocking
212	    // calls like `spawn` or `broadcast_spawn`, but a lot of stuff does work fine.
213	    //
214	    // Notably, this allows current WebAssembly targets to work even though their threading support
215	    // is stubbed out, and we won't have to change anything if they do add real threading.
216	    let unsupported = matches!(&result, Err(e) if e.is_unsupported());
217	    if unsupported && WorkerThread::current().is_null() {
218	        let builder = ThreadPoolBuilder::new().num_threads(1).use_current_thread();
219	        let fallback_result = Registry::new(builder);
220	        if fallback_result.is_ok() {
221	            return fallback_result;
222	        }
223	    }
224	
225	    result
226	}
