322	    pub(super) fn current() -> Arc<Registry> {
323	        unsafe {
324	            let worker_thread = WorkerThread::current();
325	            let registry = if worker_thread.is_null() {
326	                global_registry()
327	            } else {
328	                &(*worker_thread).registry
329	            };
330	            Arc::clone(registry)
331	        }
332	    }
