373	    pub(super) fn catch_unwind(&self, f: impl FnOnce()) {
374	        if let Err(err) = unwind::halt_unwinding(f) {
375	            // If there is no handler, or if that handler itself panics, then we abort.
376	            let abort_guard = unwind::AbortIfPanic;
377	            if let Some(ref handler) = self.panic_handler {
378	                handler(err);
379	                mem::forget(abort_guard);
380	            }
381	        }
382	    }
