384	    /// Waits for the worker threads to get up and running.  This is
385	    /// meant to be used for benchmarking purposes, primarily, so that
386	    /// you can get more consistent numbers by having everything
387	    /// "ready to go".
388	    pub(super) fn wait_until_primed(&self) {
389	        for info in &self.thread_infos {
390	            info.primed.wait();
391	        }
392	    }
