403	    // ////////////////////////////////////////////////////////////////////////
404	    // MAIN LOOP
405	    //
406	    // So long as all of the worker threads are hanging out in their
407	    // top-level loop, there is no work to be done.
408	
409	    /// Push a job into the given `registry`. If we are running on a
410	    /// worker thread for the registry, this will push onto the
411	    /// deque. Else, it will inject from the outside (which is slower).
412	    pub(super) fn inject_or_push(&self, job_ref: JobRef) {
413	        let worker_thread = WorkerThread::current();
414	        unsafe {
415	            if !worker_thread.is_null() && (*worker_thread).registry().id() == self.id() {
416	                (*worker_thread).push(job_ref);
417	            } else {
418	                self.inject(job_ref);
419	            }
420	        }
421	    }
422	
423	    /// Push a job into the "external jobs" queue; it will be taken by
424	    /// whatever worker has nothing to do. Use this if you know that
425	    /// you are not on a worker of this registry.
426	    pub(super) fn inject(&self, injected_job: JobRef) {
427	        // It should not be possible for `state.terminate` to be true
428	        // here. It is only set to true when the user creates (and
429	        // drops) a `ThreadPool`; and, in that case, they cannot be
430	        // calling `inject()` later, since they dropped their
431	        // `ThreadPool`.
432	        debug_assert_ne!(
433	            self.terminate_count.load(Ordering::Acquire),
434	            0,
435	            "inject() sees state.terminate as true"
436	        );
437	
438	        let queue_was_empty = self.injected_jobs.is_empty();
439	
440	        self.injected_jobs.push(injected_job);
441	        self.sleep.new_injected_jobs(1, queue_was_empty);
442	    }
443	
444	    fn has_injected_job(&self) -> bool {
445	        !self.injected_jobs.is_empty()
446	    }
447	
448	    fn pop_injected_job(&self) -> Option<JobRef> {
449	        loop {
450	            match self.injected_jobs.steal() {
451	                Steal::Success(job) => return Some(job),
452	                Steal::Empty => return None,
453	                Steal::Retry => std::hint::spin_loop(),
454	            }
455	        }
456	    }
457	
458	    /// Push a job into each thread's own "external jobs" queue; it will be
459	    /// executed only on that thread, when it has nothing else to do locally,
460	    /// before it tries to steal other work.
461	    ///
462	    /// **Panics** if not given exactly as many jobs as there are threads.
463	    pub(super) fn inject_broadcast(&self, injected_jobs: impl ExactSizeIterator<Item = JobRef>) {
464	        assert_eq!(self.num_threads(), injected_jobs.len());
465	        {
466	            let broadcasts = self.broadcasts.lock().unwrap();
467	
468	            // It should not be possible for `state.terminate` to be true
469	            // here. It is only set to true when the user creates (and
470	            // drops) a `ThreadPool`; and, in that case, they cannot be
471	            // calling `inject_broadcast()` later, since they dropped their
472	            // `ThreadPool`.
473	            debug_assert_ne!(
474	                self.terminate_count.load(Ordering::Acquire),
475	                0,
476	                "inject_broadcast() sees state.terminate as true"
477	            );
478	
479	            assert_eq!(broadcasts.len(), injected_jobs.len());
480	            for (worker, job_ref) in broadcasts.iter().zip(injected_jobs) {
481	                worker.push(job_ref);
482	            }
483	        }
484	        for i in 0..self.num_threads() {
485	            self.sleep.notify_worker_latch_is_set(i);
486	        }
487	    }
488	
489	    /// If already in a worker-thread of this registry, just execute `op`.
490	    /// Otherwise, inject `op` in this thread pool. Either way, block until `op`
491	    /// completes and return its return value. If `op` panics, that panic will
492	    /// be propagated as well.  The second argument indicates `true` if injection
493	    /// was performed, `false` if executed directly.
494	    pub(super) fn in_worker<OP, R>(&self, op: OP) -> R
495	    where
496	        OP: FnOnce(&WorkerThread, bool) -> R + Send,
497	        R: Send,
498	    {
499	        unsafe {
500	            let worker_thread = WorkerThread::current();
501	            if worker_thread.is_null() {
502	                self.in_worker_cold(op)
503	            } else if (*worker_thread).registry().id() != self.id() {
504	                self.in_worker_cross(&*worker_thread, op)
505	            } else {
506	                // Perfectly valid to give them a `&T`: this is the
507	                // current thread, so we know the data structure won't be
508	                // invalidated until we return.
509	                op(&*worker_thread, false)
510	            }
511	        }
512	    }
513	
514	    #[cold]
515	    unsafe fn in_worker_cold<OP, R>(&self, op: OP) -> R
516	    where
517	        OP: FnOnce(&WorkerThread, bool) -> R + Send,
518	        R: Send,
519	    {
520	        thread_local!(static LOCK_LATCH: LockLatch = const { LockLatch::new() });
521	
522	        LOCK_LATCH.with(|l| unsafe {
523	            // This thread isn't a member of *any* thread pool, so just block.
524	            debug_assert!(WorkerThread::current().is_null());
525	            let job = StackJob::new(
526	                |injected| {
527	                    let worker_thread = WorkerThread::current();
528	                    assert!(injected && !worker_thread.is_null());
529	                    op(&*worker_thread, true)
530	                },
531	                LatchRef::new(l),
532	            );
533	            self.inject(job.as_job_ref());
534	            job.latch.wait_and_reset(); // Make sure we can use the same latch again next time.
535	
536	            job.into_result()
537	        })
538	    }
539	
540	    #[cold]
541	    unsafe fn in_worker_cross<OP, R>(&self, current_thread: &WorkerThread, op: OP) -> R
542	    where
543	        OP: FnOnce(&WorkerThread, bool) -> R + Send,
544	        R: Send,
545	    {
546	        unsafe {
547	            // This thread is a member of a different pool, so let it process
548	            // other work while waiting for this `op` to complete.
549	            debug_assert!(current_thread.registry().id() != self.id());
550	            let latch = SpinLatch::cross(current_thread);
551	            let job = StackJob::new(
552	                |injected| {
553	                    let worker_thread = WorkerThread::current();
554	                    assert!(injected && !worker_thread.is_null());
555	                    op(&*worker_thread, true)
556	                },
557	                latch,
558	            );
559	            self.inject(job.as_job_ref());
560	            current_thread.wait_until(&job.latch);
561	            job.into_result()
562	        }
563	    }
564	
565	    /// Increments the terminate counter. This increment should be
566	    /// balanced by a call to `terminate`, which will decrement. This
567	    /// is used when spawning asynchronous work, which needs to
568	    /// prevent the registry from terminating so long as it is active.
569	    ///
570	    /// Note that blocking functions such as `join` and `scope` do not
571	    /// need to concern themselves with this fn; their context is
572	    /// responsible for ensuring the current thread pool will not
573	    /// terminate until they return.
574	    ///
575	    /// The global thread pool always has an outstanding reference
576	    /// (the initial one). Custom thread pools have one outstanding
577	    /// reference that is dropped when the `ThreadPool` is dropped:
578	    /// since installing the thread pool blocks until any joins/scopes
579	    /// complete, this ensures that joins/scopes are covered.
580	    ///
581	    /// The exception is `::spawn()`, which can create a job outside
582	    /// of any blocking scope. In that case, the job itself holds a
583	    /// terminate count and is responsible for invoking `terminate()`
584	    /// when finished.
585	    pub(super) fn increment_terminate_count(&self) {
586	        let previous = self.terminate_count.fetch_add(1, Ordering::AcqRel);
587	        debug_assert!(previous != 0, "registry ref count incremented from zero");
588	        assert!(previous != usize::MAX, "overflow in registry ref count");
589	    }
590	
591	    /// Signals that the thread pool which owns this registry has been
592	    /// dropped. The worker threads will gradually terminate, once any
593	    /// extant work is completed.
594	    pub(super) fn terminate(&self) {
595	        if self.terminate_count.fetch_sub(1, Ordering::AcqRel) == 1 {
596	            for (i, thread_info) in self.thread_infos.iter().enumerate() {
597	                unsafe { OnceLatch::set_and_tickle_one(&thread_info.terminate, self, i) };
598	            }
599	        }
600	    }
601	
602	    /// Notify the worker that the latch they are sleeping on has been "set".
603	    pub(super) fn notify_worker_latch_is_set(&self, target_worker_index: usize) {
604	        self.sleep.notify_worker_latch_is_set(target_worker_index);
605	    }
606	}
